style.css:
body {
    background-image: url('https://i0.wp.com/godandidotblog.wordpress.com/wp-content/uploads/2018/12/Christmas_animated-GIF-1.gif');
    background-size: cover; /* Ensures the background image covers the entire viewport */
    background-position: center center; /* Centers the background image */
    background-attachment: fixed; /* Keeps the background fixed when scrolling */
    background-repeat: no-repeat; /* Ensures the image doesn't repeat */
    height: 100vh; /* Ensures the background covers the full height of the viewport */
    margin: 0; /* Removes any default margin from the body */
    color: white; /* Makes the text more readable on the background */
    font-family: Arial, sans-serif;
}

h1 {
    text-align: center;
    padding-top: 50px; /* Add space at the top */
}

p {
    text-align: center;
    font-size: 18px;
}
